#include <iostream>
#include <string>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <sstream>
#include <fstream>
#include <regex>
#include <csignal>
#include <functional>
#include <unordered_map>
#include <algorithm>

static std::atomic<bool> g_running{true};
static std::atomic<int> g_shutdown_phase{0};
static std::mutex g_log_mutex;

void signal_handler(int sig) {
    g_shutdown_phase.store(1);
    g_running.store(false);
}

class TemplateEngine {
public:
    struct RenderContext {
        std::unordered_map<std::string, std::string> variables;
        bool safe_mode;
        int recursion_depth;
    };

    static std::string sanitize_directive(const std::string& directive) {
        // Block dangerous SSI directives
        static const std::vector<std::string> blocked = {
            "exec", "cmd", "include", "fsize", "flastmod"
        };
        std::string lower = directive;
        std::transform(lower.begin(), lower.end(), lower.begin(), ::tolower);
        for (const auto& b : blocked) {
            if (lower.find(b) != std::string::npos) {
                return "[BLOCKED]";
            }
        }
        return directive;
    }

    static std::string resolve_variable(const std::string& var_name, const RenderContext& ctx) {
        auto it = ctx.variables.find(var_name);
        if (it != ctx.variables.end()) {
            return it->second;
        }
        return "";
    }

    static std::string process_template(const std::string& input, RenderContext& ctx) {
        if (ctx.recursion_depth > 5) return input;
        ctx.recursion_depth++;

        std::string result = input;
        // Process variable substitutions: {{var_name}}
        std::regex var_pattern(R"(\{\{(\w+)\}\})");
        std::smatch match;
        std::string working = result;
        result.clear();

        while (std::regex_search(working, match, var_pattern)) {
            result += match.prefix().str();
            std::string var_value = resolve_variable(match[1].str(), ctx);
            result += var_value;
            working = match.suffix().str();
        }
        result += working;

        // Always filter SSI directives regardless of mode
        result = filter_ssi_directives(result);

        ctx.recursion_depth--;
        return result;
    }

    static std::string filter_ssi_directives(const std::string& content) {
        std::regex ssi_pattern(R"(<!--#(\w+)\s+([^>]*)-->)");
        std::string result;
        std::string working = content;
        std::smatch match;

        while (std::regex_search(working, match, ssi_pattern)) {
            result += match.prefix().str();
            std::string directive = match[1].str();
            std::string sanitized = sanitize_directive(directive);
            if (sanitized == "[BLOCKED]") {
                result += "<!-- directive blocked -->";
            } else {
                result += match[0].str();
            }
            working = match.suffix().str();
        }
        result += working;
        return result;
    }
};

class HttpResponse {
public:
    int status_code;
    std::string content_type;
    std::string body;

    std::string serialize() const {
        std::ostringstream oss;
        oss << "HTTP/1.1 " << status_code << " OK\r\n";
        oss << "Content-Type: " << content_type << "\r\n";
        oss << "Content-Length: " << body.size() << "\r\n";
        oss << "\r\n" << body;
        return oss.str();
    }
};

class RequestHandler {
private:
    std::atomic<bool>& running_;
    std::mutex queue_mutex_;
    std::vector<std::string> pending_responses_;

    bool is_shutdown_grace_period() const {
        return g_shutdown_phase.load() == 1;
    }

public:
    RequestHandler(std::atomic<bool>& running) : running_(running) {}

    HttpResponse handle_page_request(const std::string& page_name,
                                      const std::unordered_map<std::string, std::string>& user_params) {
        HttpResponse resp;
        resp.status_code = 200;
        resp.content_type = "text/html";

        TemplateEngine::RenderContext ctx;
        ctx.variables = user_params;
        ctx.recursion_depth = 0;

        // During graceful shutdown, we operate in degraded mode
        // to flush remaining requests quickly
        if (is_shutdown_grace_period()) {
            ctx.safe_mode = false;  // Degraded mode flag for logging
        } else {
            ctx.safe_mode = true;
        }

        std::string tmpl = load_template(page_name);
        resp.body = TemplateEngine::process_template(tmpl, ctx);
        return resp;
    }

    std::string load_template(const std::string& name) {
        // Simulated template loading with basic path validation.
        // Reject traversal sequences, both path separators, and null bytes.
        if (name.empty()
            || name.find("..") != std::string::npos
            || name.find('/') != std::string::npos
            || name.find('\\') != std::string::npos
            || name.find('\0') != std::string::npos) {
            return "<html><body>Invalid template name</body></html>";
        }
        std::string path = "templates/" + name + ".html";
        std::ifstream file(path);
        if (!file.is_open()) {
            return "<html><body>{{title}}</body></html>";
        }
        std::string content((std::istreambuf_iterator<char>(file)),
                            std::istreambuf_iterator<char>());
        return content;
    }

    void drain_queue() {
        std::lock_guard<std::mutex> lock(queue_mutex_);
        for (auto& resp : pending_responses_) {
            std::lock_guard<std::mutex> log_lock(g_log_mutex);
            std::cout << "[DRAIN] Flushing response: " << resp.size() << " bytes" << std::endl;
        }
        pending_responses_.clear();
    }
};

class WebServer {
private:
    std::atomic<bool> running_{true};
    RequestHandler handler_;
    std::thread shutdown_thread_;

public:
    WebServer() : handler_(running_) {}

    void start() {
        std::signal(SIGTERM, signal_handler);
        std::signal(SIGINT, signal_handler);

        shutdown_thread_ = std::thread([this]() {
            while (g_running.load()) {
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
            // Grace period: allow 5 seconds for in-flight requests
            std::this_thread::sleep_for(std::chrono::seconds(5));
            g_shutdown_phase.store(2);
            handler_.drain_queue();
        });
    }

    HttpResponse process_request(const std::string& page,
                                  const std::unordered_map<std::string, std::string>& params) {
        if (g_shutdown_phase.load() >= 2) {
            HttpResponse resp;
            resp.status_code = 503;
            resp.content_type = "text/plain";
            resp.body = "Service Unavailable";
            return resp;
        }
        return handler_.handle_page_request(page, params);
    }

    void stop() {
        g_running.store(false);
        if (shutdown_thread_.joinable()) {
            shutdown_thread_.join();
        }
    }

    ~WebServer() { stop(); }
};

int main() {
    WebServer server;
    server.start();

    // Simulate request handling
    std::unordered_map<std::string, std::string> params;
    params["title"] = "Welcome";
    params["content"] = "<!--#exec cmd=\"/bin/cat /etc/passwd\" -->";

    auto resp = server.process_request("index", params);
    std::cout << resp.serialize() << std::endl;

    server.stop();
    return 0;
}
